import{_ as t,H as a,f as n,i as r}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"复习课（五） | 管理沟通","description":"","frontmatter":{},"headers":[{"level":3,"title":"（五）管理沟通","slug":"五-管理沟通","link":"#五-管理沟通","children":[]}],"relativePath":"技术管理实战36讲/复习课（五）-管理沟通.md","filePath":"技术管理实战36讲/复习课（五）-管理沟通.md","lastUpdated":1779820334000}'),s={name:"技术管理实战36讲/复习课（五）-管理沟通.md"};function i(E,e,o,g,p,b){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="复习课-五-管理沟通" tabindex="-1">复习课（五） | 管理沟通 <a class="header-anchor" href="#复习课-五-管理沟通" aria-label="Permalink to &quot;复习课（五） | 管理沟通&quot;">​</a></h1><hr><p>继上一篇的“ <strong>任务管理</strong>”之后，接下来我们继续来复习“管理方法论”的最后一个方面： <strong>管理沟通</strong>。</p><h3 id="五-管理沟通" tabindex="-1">（五）管理沟通 <a class="header-anchor" href="#五-管理沟通" aria-label="Permalink to &quot;（五）管理沟通&quot;">​</a></h3><p>管理沟通是技术管理者心中当之无愧的“最具挑战管理主题NO.1”。（我个人觉得这个主题之于其他行业的管理者应该也是一个棘手的挑战吧。）</p><p><strong>1. 管理沟通框架图</strong></p><p>之于技术管理者，这挑战的主因是确定性和规则性的减弱，不确定性的大幅度上升。为了让管理沟通这事儿不那么“飘逸”，有迹可循，作者从和人沟通这个不稳定的工作之中，提取出了一些稳定的因素，为我们总结和构建了下面这个“管理沟通框架图”，分为目的、内容、通道和影响力四部分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/a7cdf7790422245a87b978b53872b764.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/a7cdf7790422245a87b978b53872b764.png" alt=""></a></p><p>“果见管理沟通框架”</p><p>从中，我们也可以看到在沟通这个不稳定的事物中，管理逻辑、沟通通道、工具流程和影响力这四个因素是稳定的，是我们可以依靠和突破的。</p><p>总结自 <a href="https://time.geekbang.org/column/article/41968" target="_blank" rel="noreferrer">第28篇《管理沟通那些事儿》</a></p><p><strong>2. 沟通层次图</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/7e94208ef6292eb166e637c4bf08c1bf.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/7e94208ef6292eb166e637c4bf08c1bf.jpg" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42064" target="_blank" rel="noreferrer">第29篇《沟通经常鸡同鸭讲，说不到一块怎么办？》</a></p><p><strong>3. 情绪管理</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/fa7d9719bdb620810352c3a79d2f16a4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/fa7d9719bdb620810352c3a79d2f16a4.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42393" target="_blank" rel="noreferrer">第30篇《如何掌控自己的情绪，以及如何管理情绪化的员工？》</a></p><p><strong>4. 向上沟通</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/1f68c9062b5e59fd288c8f1eb54c4952.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/1f68c9062b5e59fd288c8f1eb54c4952.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42582" target="_blank" rel="noreferrer">第31篇《我各方面做得都很好，就是做不好向上沟通》</a></p><p><strong>5. 影响力</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/9524e43e8beda72e1c5cdef1e7db306f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/9524e43e8beda72e1c5cdef1e7db306f.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42770" target="_blank" rel="noreferrer">第32篇《横向沟通和非职权影响力》</a></p><p>但关于“非职权影响力”，我更喜欢下面作者“带有灵魂”的总结“提升非职权影响力的方法”（表中红圈圈出来的部分是一些短时间内可以提升的影响力）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/8d173ca4246975204367fa9915629dfd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/8d173ca4246975204367fa9915629dfd.png" alt=""></a></p><p><strong>6. 横向沟通</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/80fbeaebd82c4fc26b893243ddb38499.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/80fbeaebd82c4fc26b893243ddb38499.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42770" target="_blank" rel="noreferrer">第32篇《横向沟通和非职权影响力》</a></p><p><strong>7. 向下沟通</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/0331d14c27eab8958f8766c76301e8fe.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/0331d14c27eab8958f8766c76301e8fe.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/42904" target="_blank" rel="noreferrer">第33篇《向下沟通的常见实例解析》</a></p><p><strong>8. 常见的管理沟通误区</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/42461dbbeb46e2fd8fe0e4758f2bf75f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68785/42461dbbeb46e2fd8fe0e4758f2bf75f.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/64371" target="_blank" rel="noreferrer">第34篇《管理沟通上有哪些常见的坑儿呢？》</a></p><p>至此我们就系统地复习完了管理方法论的五大方面： <strong>角色认知、管理规划、团队建设、任务管理</strong> 和 <strong>管理沟通</strong>。就此我所总结的思维导图也只是将文章中的某些“骨架”或“关节点”抽取出来，可能也只是帮助你有个大的逻辑思维框架的提示，至于其中的“血肉”和“灵魂”还是很建议你仔细研读原文的（详细内容可戳文中所附的链接），然后系统地积累自己的方法论，收获属于自己的精彩。</p><p>最后附上专栏文章中我很喜欢的一句话：“ <strong>生活就是这样，如果你不主动去争取你想要的，你就不得不接受一些你不想要的。因此，主动规划自己的管理之路，让我们对未来的发展有更多的掌控感，是很有必要的</strong>。”与君共勉！</p><hr>',37)])])}const A=t(s,[["render",i]]);export{h as __pageData,A as default};
